import sys
import pandas as pd
import numpy as np
import json

df = pd.read_csv(sys.argv[1])

facts = []

# Helper function to convert numpy types to Python types
def to_python(val):
    if pd.isna(val):
        return None
    if isinstance(val, (np.integer, np.floating)):
        return float(val)
    return val

# 1. Top 3 entities by Revenue_TW
top_by_revenue = df.nlargest(3, 'Revenue_TW')
for idx, row in top_by_revenue.iterrows():
    if pd.notna(row['Revenue_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "TW",
            "value": round(to_python(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })

# 2. Top 3 entities by Units_TW
top_by_units = df.nlargest(3, 'Units_TW')
for idx, row in top_by_units.iterrows():
    if pd.notna(row['Units_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "units",
            "period": "TW",
            "value": int(to_python(row['Units_TW'])),
            "formula": "Units_TW"
        })

# 3. Top 3 entities by Orders_TW
top_by_orders = df.nlargest(3, 'Orders_TW')
for idx, row in top_by_orders.iterrows():
    if pd.notna(row['Orders_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "orders",
            "period": "TW",
            "value": int(to_python(row['Orders_TW'])),
            "formula": "Orders_TW"
        })

# 4. Biggest WoW movers (top 2 positive and top 2 negative)
wow_data = df[df['WoW_Pct'].notna()].copy()
if len(wow_data) > 0:
    top_wow = wow_data.nlargest(2, 'WoW_Pct')
    for idx, row in top_wow.iterrows():
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "WoW",
            "value": round(to_python(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    bottom_wow = wow_data.nsmallest(2, 'WoW_Pct')
    for idx, row in bottom_wow.iterrows():
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "WoW",
            "value": round(to_python(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

# 5. Biggest YoY movers (top 2 positive and top 2 negative)
yoy_data = df[df['YoY_Pct'].notna()].copy()
if len(yoy_data) > 0:
    top_yoy = yoy_data.nlargest(2, 'YoY_Pct')
    for idx, row in top_yoy.iterrows():
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "YoY",
            "value": round(to_python(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    bottom_yoy = yoy_data.nsmallest(2, 'YoY_Pct')
    for idx, row in bottom_yoy.iterrows():
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "YoY",
            "value": round(to_python(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

# 6. Top 3 by Share_Pct
top_by_share = df.nlargest(3, 'Share_Pct')
for idx, row in top_by_share.iterrows():
    if pd.notna(row['Share_Pct']):
        facts.append({
            "entity": row['Entity'],
            "metric": "share",
            "period": "TW",
            "value": round(to_python(row['Share_Pct']), 1),
            "formula": "Revenue_TW / sum(Revenue_TW) * 100"
        })

# 7. TOTAL metrics
total_revenue_tw = df['Revenue_TW'].sum()
total_revenue_lw = df['Revenue_LW'].sum()
total_revenue_ly = df['Revenue_LY'].sum()
total_units_tw = df['Units_TW'].sum()
total_units_lw = df['Units_LW'].sum()
total_orders_tw = df['Orders_TW'].sum()
total_orders_lw = df['Orders_LW'].sum()

if pd.notna(total_revenue_tw) and total_revenue_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "TW",
        "value": round(float(total_revenue_tw), 2),
        "formula": "sum(Revenue_TW)"
    })

if pd.notna(total_units_tw) and total_units_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "units",
        "period": "TW",
        "value": int(total_units_tw),
        "formula": "sum(Units_TW)"
    })

if pd.notna(total_orders_tw) and total_orders_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "orders",
        "period": "TW",
        "value": int(total_orders_tw),
        "formula": "sum(Orders_TW)"
    })

# 8. TOTAL WoW and YoY
if total_revenue_lw > 0 and pd.notna(total_revenue_tw):
    wow_total = (total_revenue_tw - total_revenue_lw) / total_revenue_lw * 100
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "WoW",
        "value": round(float(wow_total), 1),
        "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
    })

if total_revenue_ly > 0 and pd.notna(total_revenue_tw):
    yoy_total = (total_revenue_tw - total_revenue_ly) / total_revenue_ly * 100
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "YoY",
        "value": round(float(yoy_total), 1),
        "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
    })

# Limit to 25 facts
facts = facts[:25]

print(json.dumps(facts))
